item.aggregated_output:
Inspect the bounded semantic IR contract without scanning a project.

Usage: fr author semantic-schema [OPTIONS] [SECTION]

Arguments:
  [SECTION]  Optional contract section. [possible values: body, type, statement, expression, template, binary-operator, unary-operator, record]

Options:
      --json                   Emit machine-readable JSON instead of human-readable text
      --kind <KIND>            One kind within the selected node section.
      --max-file-size <BYTES>  Skip files larger than this many bytes (default 4194304, 4 MiB)
  -C, --root <ROOT>            Workspace root to operate on [default: .]
      --no-ignore              Read files that .gitignore and friends exclude, and hidden files too
      --no-cache               Re-read every file instead of reusing cached facts
      --save-plan              Store a checked change plan for later application through `fr history`
      --context-basis <BASIS>  Omit project or forward-transaction context previously reviewed under this basis.
      --plan-basis <BASIS>     Omit an unchanged author or migration plan reviewed under this basis.
  -h, --help                   Print help
{
  "commands": {
    "section": "fr author semantic-schema <SECTION>",
    "validate": "fr author validate-semantic --from <FILE>",
    "variant": "fr author semantic-schema <SECTION> --kind <KIND>"
  },
  "encoding": {
    "case": "kebab-case",
    "content": "value",
    "enum": "adjacently-tagged",
    "tag": "kind"
  },
  "python": {
    "object_fields": "pass as keyword arguments",
    "package": "fr_ir",
    "source_read_required": false
  },
  "schema": "fr-semantic-catalog-1",
  "sections": [
    {
      "entries": 1,
      "name": "body"
    },
    {
      "entries": 12,
      "name": "type"
